//! 🖍️ Native Draw semantic entities, exact words and actual owner I/O.
use crate::standards::v1::subsets::any::io::sqlite::snapshot::*;
fn dialect()->semio_framework_artifact_reference::ArtifactDialect {semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.draw.drawing".into(),standard:"1".into(),subset:"*".into()}}
fn provider()->store::ArtifactSqliteSnapshotCodec{<DrawingSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().expect("Draw snapshot must declare full semantic SQLite capability")}
#[test]
fn sqlite_snapshot_draw_actual_io_declaration_capability(){let codec=crate::standards::v1::subsets::any::io::io().native.codec;let p=codec.snapshot_sqlite.expect("actual Draw native declaration must publish semantic SQLite capability");assert_eq!(p.snapshot_type,Some(std::any::TypeId::of::<DrawingSnapshot>()));}
#[test]
fn sqlite_snapshot_draw_owned_complete_fields_both_native_encodings(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let snapshot:DrawingSnapshot=serde_json::from_value(f["snapshot"].clone()).unwrap();let p=provider();for encoding in [store::sqlite_snapshot::SnapshotEncoding::Binary,store::sqlite_snapshot::SnapshotEncoding::Text]{let payload=match encoding{store::sqlite_snapshot::SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),store::sqlite_snapshot::SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};let database=(p.export)(crate::DRAWING_DOCUMENT_SCHEMA,&dialect(),&payload,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;assert_eq!(database.table("draw_layer").unwrap().rows.len(),8);assert_eq!(database.table("draw_segment").unwrap().rows.len(),6);let result=(p.import)(crate::DRAWING_DOCUMENT_SCHEMA,&dialect(),database.clone(),encoding,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;let restored=match result{store::os_io::IoPayload::Binary(bytes)=>store::ArtifactPack::decode_pack(&bytes).unwrap(),store::os_io::IoPayload::Text(text)=>store::ArtifactDsl::parse_dsl(&text).unwrap()};assert_eq!(snapshot,restored);}}
#[test]
fn sqlite_snapshot_draw_exact_foreign_dialect_and_initial_cancellation(){let p=provider();let snapshot=DrawingSnapshot::default();let payload=store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot));let mut foreign=dialect();foreign.artifact_kind="s.stdio.semio".into();assert!((p.export)(crate::DRAWING_DOCUMENT_SCHEMA,&foreign,&payload,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());assert!((p.export)(crate::DRAWING_DOCUMENT_SCHEMA,&dialect(),&payload,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|false,Default::default())).is_err());}

fn assert_draw_words(database:&store::sqlite_snapshot::SqliteDatabase,word:u64){
 let scalars=&database.table("draw_scalar").unwrap().rows;assert!(scalars.len()>100);for row in scalars{assert_eq!(row.integer(2).unwrap() as u64,word);}
 let layers=&database.table("draw_layer").unwrap().rows;assert_eq!(layers.len(),8);let kinds=layers.iter().map(|row|row.text(4).unwrap()).collect::<std::collections::BTreeSet<_>>();assert_eq!(kinds.len(),7);assert_eq!(database.table("draw_segment").unwrap().rows.len(),6);
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_draw_every_scalar_word_typed_file_and_erased_native_io(){
 use store::ArtifactSqliteSnapshot;
 use store::sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,SnapshotEncoding,export_sqlite_database,import_sqlite_database};
 use {semio_framework_os_kernel::io::register_native_snapshot_codec,semio_framework_artifact_reference::Dialect,semio_framework_artifact_reference::StandardId,semio_framework_artifact_reference::SubsetId,semio_framework_os_kernel::io::io_mechanism::io_export_sqlite_snapshot,semio_framework_os_kernel::io::io_mechanism::io_import_sqlite_snapshot};
 use std::{io::Write,process::{Command,Stdio}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let finite:DrawingSnapshot=serde_json::from_value(fixture["snapshot"].clone()).unwrap();
 let limits=SqliteDatabaseLimits::default();let original=finite.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let bytes=export_sqlite_database(&original,limits,&mut |_|true).unwrap();
 let native=Dialect{artifact_kind:"s.draw.drawing",standard:StandardId("1"),subset:SubsetId("*")};register_native_snapshot_codec(native,crate::standards::v1::subsets::any::io::io().native.codec).unwrap();let coordinate=native.into();let codec=provider();
 let edit=r#"import {Database} from 'bun:sqlite';const word=BigInt('0x'+process.argv.at(-1));const view=new DataView(new ArrayBuffer(8));view.setBigUint64(0,word);const value=view.getFloat64(0),exponent=(word>>52n)&2047n,fraction=word&((1n<<52n)-1n),kind=exponent!==2047n?'finite':fraction!==0n?'nan':word>>63n===0n?'positiveInfinity':'negativeInfinity';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');db.query('UPDATE draw_scalar SET value=?,bits=?,class=?').run(kind==='nan'?null:value,BigInt.asIntN(64,word),kind);if(db.query('SELECT count(*) AS count FROM draw_scalar').get().count<=100||db.query('SELECT DISTINCT printf("%016x",bits) AS word FROM draw_scalar').all().some(row=>row.word!==process.argv.at(-1)))throw Error('word projection');await Bun.write(Bun.stdout,db.serialize());db.close();"#;
 for value in fixture["ieeeWords"].as_array().unwrap(){let hex=value.as_str().unwrap();let word=u64::from_str_radix(hex,16).unwrap();let mut child=Command::new("bun").args(["-e",edit,hex]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let database=import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap();let snapshot=DrawingSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_draw_words(&snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),word);
  for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let file=io_export_sqlite_snapshot(&coordinate,&snapshot,encoding,limits,&mut |_|true).await.unwrap().value;assert!(file.starts_with(b"SQLite format 3\0"));let restored=io_import_sqlite_snapshot::<DrawingSnapshot>(&coordinate,&file,limits,&mut |_|true).await.unwrap().value;assert_draw_words(&restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),word);
   let payload=(codec.import)(crate::DRAWING_DOCUMENT_SCHEMA,&dialect(),database.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let exported=(codec.export)(crate::DRAWING_DOCUMENT_SCHEMA,&dialect(),&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_draw_words(&exported,word);
  }
 }
}
